('KA-Environmental Science', 'ಕನ್ನಡ', 'ಖಾಲಿ ಜಾಗ ತುಂಬಿರಿ', 'ಮಧ್ಯಮ', '1', 'ತ್ಯಾಜ್ಯ ಉತ್ಪಾದನೆಯನ್ನು ಕಡಿಮೆ ಮಾಡುವುದನ್ನು ತ್ಯಾಜ್ಯ ______ ಎಂದು ಕರೆಯುತ್ತಾರೆ.', NULL, NULL, NULL, NULL, 'ಕಡಿತ', 'ಖಾಲಿ ಜಾಗಕ್ಕೆ ಹೊಂದುವ ಸರಿಯಾದ ಪರಿಸರ ವಿಜ್ಞಾನ ಪರಿಕಲ್ಪನೆಯೇ ಉತ್ತರ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಖಾಲಿ ಜಾಗ ತುಂಬಿರಿ', 'ಮಧ್ಯಮ', '1', 'ವಸ್ತುವನ್ನು ಮತ್ತೆ ಬಳಸುವುದನ್ನು ______ ಎಂದು ಕರೆಯುತ್ತಾರೆ.', NULL, NULL, NULL, NULL, 'ಮರುಬಳಕೆ', 'ಖಾಲಿ ಜಾಗಕ್ಕೆ ಹೊಂದುವ ಸರಿಯಾದ ಪರಿಸರ ವಿಜ್ಞಾನ ಪರಿಕಲ್ಪನೆಯೇ ಉತ್ತರ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಖಾಲಿ ಜಾಗ ತುಂಬಿರಿ', 'ಮಧ್ಯಮ', '1', 'ತ್ಯಾಜ್ಯದಿಂದ ಹೊಸ ಉಪಯುಕ್ತ ವಸ್ತು ತಯಾರಿಸುವುದನ್ನು ______ ಎಂದು ಕರೆಯುತ್ತಾರೆ.', NULL, NULL, NULL, NULL, 'ಮರುಸಂಸ್ಕರಣೆ', 'ಖಾಲಿ ಜಾಗಕ್ಕೆ ಹೊಂದುವ ಸರಿಯಾದ ಪರಿಸರ ವಿಜ್ಞಾನ ಪರಿಕಲ್ಪನೆಯೇ ಉತ್ತರ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಖಾಲಿ ಜಾಗ ತುಂಬಿರಿ', 'ಕಠಿಣ', '1', 'ಪ್ರಸ್ತುತ ಮತ್ತು ಭವಿಷ್ಯದ ಅಗತ್ಯಗಳನ್ನು ಸಮತೋಲನಗೊಳಿಸುವ ಅಭಿವೃದ್ಧಿಯನ್ನು ______ ಅಭಿವೃದ್ಧಿ ಎನ್ನುತ್ತಾರೆ.', NULL, NULL, NULL, NULL, 'ಸುಸ್ಥಿರ', 'ಖಾಲಿ ಜಾಗಕ್ಕೆ ಹೊಂದುವ ಸರಿಯಾದ ಪರಿಸರ ವಿಜ್ಞಾನ ಪರಿಕಲ್ಪನೆಯೇ ಉತ್ತರ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಖಾಲಿ ಜಾಗ ತುಂಬಿರಿ', 'ಕಠಿಣ', '1', 'ವನ್ಯಜೀವಿ ಮತ್ತು ಅವುಗಳ ವಾಸಸ್ಥಳ ರಕ್ಷಣೆಯನ್ನು ______ ಸಂರಕ್ಷಣೆ ಎನ್ನುತ್ತಾರೆ.', NULL, NULL, NULL, NULL, 'ವನ್ಯಜೀವಿ', 'ಖಾಲಿ ಜಾಗಕ್ಕೆ ಹೊಂದುವ ಸರಿಯಾದ ಪರಿಸರ ವಿಜ್ಞಾನ ಪರಿಕಲ್ಪನೆಯೇ ಉತ್ತರ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಖಾಲಿ ಜಾಗ ತುಂಬಿರಿ', 'ಕಠಿಣ', '1', 'ಅತಿಯಾದ ಶಬ್ದದಿಂದ ಉಂಟಾಗುವ ಮಾಲಿನ್ಯವನ್ನು ______ ಮಾಲಿನ್ಯ ಎನ್ನುತ್ತಾರೆ.', NULL, NULL, NULL, NULL, 'ಧ್ವನಿ', 'ಖಾಲಿ ಜಾಗಕ್ಕೆ ಹೊಂದುವ ಸರಿಯಾದ ಪರಿಸರ ವಿಜ್ಞಾನ ಪರಿಕಲ್ಪನೆಯೇ ಉತ್ತರ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಖಾಲಿ ಜಾಗ ತುಂಬಿರಿ', 'ಕಠಿಣ', '1', 'ಮಾನವ ಚಟುವಟಿಕೆಗಳಿಂದ ಉಂಟಾಗುವ ಹಸಿರುಮನೆ ಅನಿಲ ಹೊರಸೂಸುವಿಕೆಯ ಪ್ರಮಾಣವನ್ನು ಕಾರ್ಬನ್ ______ ಎನ್ನುತ್ತಾರೆ.', NULL, NULL, NULL, NULL, 'ಪಾದಚಿಹ್ನೆ', 'ಖಾಲಿ ಜಾಗಕ್ಕೆ ಹೊಂದುವ ಸರಿಯಾದ ಪರಿಸರ ವಿಜ್ಞಾನ ಪರಿಕಲ್ಪನೆಯೇ ಉತ್ತರ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಖಾಲಿ ಜಾಗ ತುಂಬಿರಿ', 'ಕಠಿಣ', '1', 'ದೀರ್ಘಕಾಲದ ಹವಾಮಾನ ಮಾದರಿಗಳ ಬದಲಾವಣೆಯನ್ನು ಹವಾಮಾನ ______ ಎಂದು ಕರೆಯುತ್ತಾರೆ.', NULL, NULL, NULL, NULL, 'ಬದಲಾವಣೆ', 'ಖಾಲಿ ಜಾಗಕ್ಕೆ ಹೊಂದುವ ಸರಿಯಾದ ಪರಿಸರ ವಿಜ್ಞಾನ ಪರಿಕಲ್ಪನೆಯೇ ಉತ್ತರ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಖಾಲಿ ಜಾಗ ತುಂಬಿರಿ', 'ಕಠಿಣ', '1', 'ಪರಿಸರದ ಬಗ್ಗೆ ಜ್ಞಾನ ಮತ್ತು ಜವಾಬ್ದಾರಿ ಬೆಳೆಸುವುದನ್ನು ಪರಿಸರ ______ ಎನ್ನುತ್ತಾರೆ.', NULL, NULL, NULL, NULL, 'ಶಿಕ್ಷಣ', 'ಖಾಲಿ ಜಾಗಕ್ಕೆ ಹೊಂದುವ ಸರಿಯಾದ ಪರಿಸರ ವಿಜ್ಞಾನ ಪರಿಕಲ್ಪನೆಯೇ ಉತ್ತರ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಖಾಲಿ ಜಾಗ ತುಂಬಿರಿ', 'ಕಠಿಣ', '1', 'ಸಮಾನ ಜೀವಿಗಳ ಮತ್ತು ಪರಿಸರಗಳ ವೈವಿಧ್ಯತೆಯನ್ನು ಕಾಪಾಡುವುದು ಜೈವ ವೈವಿಧ್ಯತೆ ______ಗೆ ಮುಖ್ಯ.', NULL, NULL, NULL, NULL, 'ಸಂರಕ್ಷಣೆ', 'ಖಾಲಿ ಜಾಗಕ್ಕೆ ಹೊಂದುವ ಸರಿಯಾದ ಪರಿಸರ ವಿಜ್ಞಾನ ಪರಿಕಲ್ಪನೆಯೇ ಉತ್ತರ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಖಾಲಿ ಜಾಗ ತುಂಬಿರಿ', 'ಕಠಿಣ', '1', 'ನೀರಿನ ವ್ಯರ್ಥ ಬಳಕೆಯನ್ನು ಕಡಿಮೆ ಮಾಡುವುದನ್ನು ನೀರಿನ ______ ಎಂದು ಕರೆಯುತ್ತಾರೆ.', NULL, NULL, NULL, NULL, 'ಸಂರಕ್ಷಣೆ', 'ಖಾಲಿ ಜಾಗಕ್ಕೆ ಹೊಂದುವ ಸರಿಯಾದ ಪರಿಸರ ವಿಜ್ಞಾನ ಪರಿಕಲ್ಪನೆಯೇ ಉತ್ತರ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಖಾಲಿ ಜಾಗ ತುಂಬಿರಿ', 'ಕಠಿಣ', '1', 'ಮಣ್ಣಿನ ಗುಣ ಮತ್ತು ಮೇಲ್ಮಣ್ಣನ್ನು ಕಾಪಾಡುವ ಕ್ರಮವನ್ನು ಮಣ್ಣಿನ ______ ಎಂದು ಕರೆಯುತ್ತಾರೆ.', NULL, NULL, NULL, NULL, 'ಸಂರಕ್ಷಣೆ', 'ಖಾಲಿ ಜಾಗಕ್ಕೆ ಹೊಂದುವ ಸರಿಯಾದ ಪರಿಸರ ವಿಜ್ಞಾನ ಪರಿಕಲ್ಪನೆಯೇ ಉತ್ತರ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಖಾಲಿ ಜಾಗ ತುಂಬಿರಿ', 'ಕಠಿಣ', '1', 'ಪರಿಸರಕ್ಕೆ ಹಾನಿ ಉಂಟುಮಾಡುವ ವಸ್ತುಗಳ ಅನಗತ್ಯ ಸೇರ್ಪಡೆಯನ್ನು ______ ಎಂದು ಕರೆಯುತ್ತಾರೆ.', NULL, NULL, NULL, NULL, 'ಮಾಲಿನ್ಯ', 'ಖಾಲಿ ಜಾಗಕ್ಕೆ ಹೊಂದುವ ಸರಿಯಾದ ಪರಿಸರ ವಿಜ್ಞಾನ ಪರಿಕಲ್ಪನೆಯೇ ಉತ್ತರ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ಪರಿಸರ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಜೀವಿಗಳು ಮತ್ತು ಅವುಗಳ ಸುತ್ತಲಿನ ಜೈವಿಕ ಹಾಗೂ ಅಜೈವಿಕ ಅಂಶಗಳ ಪರಸ್ಪರ ಸಂಬಂಧಿತ ವ್ಯವಸ್ಥೆಯೇ ಪರಿಸರ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ಪರಿಸರ ವ್ಯವಸ್ಥೆ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಜೀವಿಗಳು ಮತ್ತು ಅಜೀವ ಅಂಶಗಳು ಪರಸ್ಪರ ಕ್ರಿಯೆ ನಡೆಸುವ ನೈಸರ್ಗಿಕ ವ್ಯವಸ್ಥೆಯೇ ಪರಿಸರ ವ್ಯವಸ್ಥೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ಜೈವಿಕ ಅಂಶಗಳು ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಸಸ್ಯಗಳು, ಪ್ರಾಣಿಗಳು, ಸೂಕ್ಷ್ಮಜೀವಿಗಳು ಮತ್ತು ಇತರ ಜೀವಂತ ಘಟಕಗಳನ್ನು ಜೈವಿಕ ಅಂಶಗಳು ಎನ್ನುತ್ತಾರೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ಅಜೈವಿಕ ಅಂಶಗಳು ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ನೀರು, ಗಾಳಿ, ಮಣ್ಣು, ಬೆಳಕು ಮತ್ತು ತಾಪಮಾನ ಮುಂತಾದ ಜೀವವಿಲ್ಲದ ಅಂಶಗಳನ್ನು ಅಜೈವಿಕ ಅಂಶಗಳು ಎನ್ನುತ್ತಾರೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ಜೈವ ವೈವಿಧ್ಯತೆ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಭೂಮಿಯಲ್ಲಿರುವ ವಿವಿಧ ಜೀವಿಗಳು, ಅವುಗಳ ಜಾತಿಗಳು ಮತ್ತು ಪರಿಸರಗಳ ವೈವಿಧ್ಯತೆಯೇ ಜೈವ ವೈವಿಧ್ಯತೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ಆಹಾರ ಸರಪಳಿ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಒಂದು ಜೀವಿಯಿಂದ ಮತ್ತೊಂದು ಜೀವಿಗೆ ಆಹಾರ ಮತ್ತು ಶಕ್ತಿಯ ವರ್ಗಾವಣೆ ನಡೆಯುವ ಕ್ರಮವೇ ಆಹಾರ ಸರಪಳಿ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ಉತ್ಪಾದಕರು ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಸ್ವತಃ ಆಹಾರ ತಯಾರಿಸಿಕೊಳ್ಳುವ ಸಸ್ಯಗಳಂತಹ ಜೀವಿಗಳನ್ನು ಉತ್ಪಾದಕರು ಎನ್ನುತ್ತಾರೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ವಿಘಟಕರು ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಸತ್ತ ಜೈವಿಕ ವಸ್ತುಗಳನ್ನು ಸರಳ ಪದಾರ್ಥಗಳಾಗಿ ವಿಭಜಿಸುವ ಜೀವಿಗಳನ್ನು ವಿಘಟಕರು ಎನ್ನುತ್ತಾರೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ಅರಣ್ಯ ನಾಶ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಅರಣ್ಯ ಪ್ರದೇಶದಲ್ಲಿನ ಮರಗಳು ಮತ್ತು ನೈಸರ್ಗಿಕ ಸಸ್ಯಾವರಣವನ್ನು ವ್ಯಾಪಕವಾಗಿ ತೆರವುಗೊಳಿಸುವುದೇ ಅರಣ್ಯ ನಾಶ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಸುಲಭ', '2', 'ಮಣ್ಣಿನ ಸವಕಳಿ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಗಾಳಿ ಅಥವಾ ನೀರಿನಂತಹ ಅಂಶಗಳಿಂದ ಮೇಲ್ಮಣ್ಣು ಕೊಚ್ಚಿಹೋಗುವ ಪ್ರಕ್ರಿಯೆಯೇ ಮಣ್ಣಿನ ಸವಕಳಿ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '2', 'ವಾಯು ಮಾಲಿನ್ಯ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಹಾನಿಕಾರಕ ಅನಿಲಗಳು, ಕಣಗಳು ಅಥವಾ ಹೊಗೆಯು ಗಾಳಿಯಲ್ಲಿ ಅನಗತ್ಯವಾಗಿ ಹೆಚ್ಚಾಗುವ ಸ್ಥಿತಿಯೇ ವಾಯು ಮಾಲಿನ್ಯ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '2', 'ನೀರಿನ ಮಾಲಿನ್ಯ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಹಾನಿಕಾರಕ ವಸ್ತುಗಳು ನೀರಿನ ಗುಣಮಟ್ಟವನ್ನು ಹಾಳುಮಾಡುವ ಸ್ಥಿತಿಯೇ ನೀರಿನ ಮಾಲಿನ್ಯ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '2', 'ಮಣ್ಣಿನ ಮಾಲಿನ್ಯ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಹಾನಿಕಾರಕ ರಾಸಾಯನಿಕಗಳು ಮತ್ತು ತ್ಯಾಜ್ಯಗಳಿಂದ ಮಣ್ಣಿನ ಗುಣಮಟ್ಟ ಕುಸಿಯುವುದೇ ಮಣ್ಣಿನ ಮಾಲಿನ್ಯ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '2', 'ಹಸಿರುಮನೆ ಪರಿಣಾಮ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ವಾತಾವರಣದಲ್ಲಿನ ಕೆಲವು ಅನಿಲಗಳು ಭೂಮಿಯಿಂದ ಹೊರಹೋಗುವ ಉಷ್ಣತೆಯನ್ನು ಹಿಡಿದಿಡುವ ನೈಸರ್ಗಿಕ ಪ್ರಕ್ರಿಯೆಯೇ ಹಸಿರುಮನೆ ಪರಿಣಾಮ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '2', 'ಜಾಗತಿಕ ತಾಪಮಾನ ಏರಿಕೆ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಭೂಮಿಯ ಸರಾಸರಿ ತಾಪಮಾನ ದೀರ್ಘಕಾಲದಲ್ಲಿ ಹೆಚ್ಚಾಗುವ ಸ್ಥಿತಿಯೇ ಜಾಗತಿಕ ತಾಪಮಾನ ಏರಿಕೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '2', 'ಹವಾಮಾನ ಬದಲಾವಣೆ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ದೀರ್ಘಕಾಲದಲ್ಲಿ ತಾಪಮಾನ, ಮಳೆ ಮತ್ತು ಇತರ ಹವಾಮಾನ ಮಾದರಿಗಳಲ್ಲಿ ಉಂಟಾಗುವ ಬದಲಾವಣೆಯೇ ಹವಾಮಾನ ಬದಲಾವಣೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '2', 'ಓಜೋನ್ ಪದರದ ಮಹತ್ವವೇನು?', NULL, NULL, NULL, NULL, 'ಸೂರ್ಯನ ಹಾನಿಕಾರಕ ಅತಿನೇರಳೆ ಕಿರಣಗಳ ಬಹುಭಾಗವನ್ನು ತಡೆದು ಜೀವಿಗಳನ್ನು ರಕ್ಷಿಸಲು ಓಜೋನ್ ಪದರ ಸಹಾಯ ಮಾಡುತ್ತದೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '2', 'ನವೀಕರಿಸಬಹುದಾದ ಸಂಪನ್ಮೂಲ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಸ್ವಾಭಾವಿಕವಾಗಿ ಮರುಪೂರಣಗೊಳ್ಳುವ ಸಾಮರ್ಥ್ಯ ಹೊಂದಿರುವ ಸಂಪನ್ಮೂಲವನ್ನು ನವೀಕರಿಸಬಹುದಾದ ಸಂಪನ್ಮೂಲ ಎನ್ನುತ್ತಾರೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '2', 'ಸುಸ್ಥಿರ ಅಭಿವೃದ್ಧಿ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಪ್ರಸ್ತುತ ಪೀಳಿಗೆಯ ಅಗತ್ಯಗಳನ್ನು ಪೂರೈಸುತ್ತಾ ಭವಿಷ್ಯದ ಪೀಳಿಗೆಯ ಅಗತ್ಯಗಳಿಗೆ ಹಾನಿಯಾಗದ ಅಭಿವೃದ್ಧಿಯೇ ಸುಸ್ಥಿರ ಅಭಿವೃದ್ಧಿ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '2', 'ಮಳೆನೀರು ಸಂಗ್ರಹಣೆ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಮಳೆನೀರನ್ನು ಸಂಗ್ರಹಿಸಿ ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ಬಳಸುವ ವಿಧಾನವೇ ಮಳೆನೀರು ಸಂಗ್ರಹಣೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ಮರುಬಳಕೆ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಒಂದು ವಸ್ತುವನ್ನು ತ್ಯಾಜ್ಯವನ್ನಾಗಿಸದೆ ಮತ್ತೆ ಉಪಯೋಗಿಸುವುದೇ ಮರುಬಳಕೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ಮರುಸಂಸ್ಕರಣೆ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ತ್ಯಾಜ್ಯ ವಸ್ತುಗಳನ್ನು ಸಂಸ್ಕರಿಸಿ ಹೊಸ ಉಪಯುಕ್ತ ವಸ್ತುಗಳಾಗಿ ಪರಿವರ್ತಿಸುವುದೇ ಮರುಸಂಸ್ಕರಣೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ಕಾರ್ಬನ್ ಪಾದಚಿಹ್ನೆ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಮಾನವ ಚಟುವಟಿಕೆಗಳಿಂದ ನೇರವಾಗಿ ಅಥವಾ ಪರೋಕ್ಷವಾಗಿ ಉಂಟಾಗುವ ಹಸಿರುಮನೆ ಅನಿಲ ಹೊರಸೂಸುವಿಕೆಯ ಪ್ರಮಾಣವೇ ಕಾರ್ಬನ್ ಪಾದಚಿಹ್ನೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ವನ್ಯಜೀವಿ ಸಂರಕ್ಷಣೆ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ವನ್ಯಜೀವಿಗಳು ಮತ್ತು ಅವುಗಳ ನೈಸರ್ಗಿಕ ವಾಸಸ್ಥಳಗಳನ್ನು ರಕ್ಷಿಸಿ ಉಳಿಸುವ ಪ್ರಯತ್ನವೇ ವನ್ಯಜೀವಿ ಸಂರಕ್ಷಣೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ಮಾಲಿನ್ಯ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಪರಿಸರಕ್ಕೆ ಹಾನಿಕಾರಕ ವಸ್ತುಗಳು ಅಥವಾ ಶಕ್ತಿಯ ಅನಗತ್ಯ ಸೇರ್ಪಡೆಯಿಂದ ಪರಿಸರ ಗುಣಮಟ್ಟ ಕುಸಿಯುವುದೇ ಮಾಲಿನ್ಯ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ತ್ಯಾಜ್ಯ ನಿರ್ವಹಣೆ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ತ್ಯಾಜ್ಯವನ್ನು ಕಡಿಮೆ ಮಾಡುವುದು, ವಿಂಗಡಿಸುವುದು, ಮರುಬಳಕೆ, ಮರುಸಂಸ್ಕರಣೆ ಮತ್ತು ಸುರಕ್ಷಿತ ವಿಲೇವಾರಿ ಮಾಡುವ ವ್ಯವಸ್ಥೆಯೇ ತ್ಯಾಜ್ಯ ನಿರ್ವಹಣೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ನೀರಿನ ಸಂರಕ್ಷಣೆ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ನೀರನ್ನು ಮಿತವ್ಯಯದಿಂದ ಬಳಸುವುದು, ಸೋರಿಕೆ ತಡೆಯುವುದು ಮತ್ತು ಜಲಮೂಲಗಳನ್ನು ರಕ್ಷಿಸುವುದೇ ನೀರಿನ ಸಂರಕ್ಷಣೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ಮಣ್ಣಿನ ಸಂರಕ್ಷಣೆ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಮಣ್ಣಿನ ಸವಕಳಿ ತಡೆದು ಅದರ ಫಲವತ್ತತೆ ಮತ್ತು ಗುಣಮಟ್ಟ ಕಾಪಾಡುವ ಕ್ರಮಗಳೇ ಮಣ್ಣಿನ ಸಂರಕ್ಷಣೆ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ಪರಿಸರ ಶಿಕ್ಷಣ ಎಂದರೇನು?', NULL, NULL, NULL, NULL, 'ಪರಿಸರದ ಬಗ್ಗೆ ಜ್ಞಾನ, ಜಾಗೃತಿ ಮತ್ತು ಜವಾಬ್ದಾರಿಯುತ ವರ್ತನೆ ಬೆಳೆಸುವ ಶಿಕ್ಷಣವೇ ಪರಿಸರ ಶಿಕ್ಷಣ.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರ', 'ಕಠಿಣ', '2', 'ಪರಿಸರ ಸಂರಕ್ಷಣೆಯಲ್ಲಿ ವ್ಯಕ್ತಿಯ ಪಾತ್ರವೇನು?', NULL, NULL, NULL, NULL, 'ನೀರು ಮತ್ತು ಶಕ್ತಿ ಉಳಿಸುವುದು, ತ್ಯಾಜ್ಯ ವಿಂಗಡಿಸುವುದು, ಪ್ಲಾಸ್ಟಿಕ್ ಬಳಕೆ ಕಡಿಮೆ ಮಾಡುವುದು ಮತ್ತು ಮರ ನೆಡುವಂತಹ ಕ್ರಮಗಳಿಂದ ವ್ಯಕ್ತಿ ಪರಿಸರ ಸಂರಕ್ಷಣೆಗೆ ಸಹಕರಿಸಬಹುದು.', 'ಪ್ರಶ್ನೆಯ ಪರಿಸರ ಪರಿಕಲ್ಪನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಪರಿಸರ ವ್ಯವಸ್ಥೆಯ ರಚನೆ ಮತ್ತು ಕಾರ್ಯವನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಪರಿಸರ ವ್ಯವಸ್ಥೆಯಲ್ಲಿ ಜೈವಿಕ ಮತ್ತು ಅಜೈವಿಕ ಅಂಶಗಳು ಸೇರಿವೆ. ಸಸ್ಯಗಳು ಉತ್ಪಾದಕರಾಗಿ ಆಹಾರ ತಯಾರಿಸುತ್ತವೆ. ಗ್ರಾಹಕರು ಆಹಾರ ಸರಪಳಿಯ ವಿವಿಧ ಹಂತಗಳಲ್ಲಿ ಶಕ್ತಿಯನ್ನು ಪಡೆಯುತ್ತಾರೆ. ವಿಘಟಕರು ಸತ್ತ ವಸ್ತುಗಳನ್ನು ವಿಭಜಿಸಿ ಪೋಷಕಾಂಶಗಳನ್ನು ಪರಿಸರಕ್ಕೆ ಮರಳಿಸುತ್ತಾರೆ. ಹೀಗಾಗಿ ಶಕ್ತಿ ಹರಿವು ಮತ್ತು ಪೋಷಕಾಂಶಗಳ ಚಕ್ರ ಪರಿಸರ ವ್ಯವಸ್ಥೆಯ ಕಾರ್ಯಕ್ಕೆ ಮುಖ್ಯ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಜೈವ ವೈವಿಧ್ಯತೆಯ ಮಹತ್ವವನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಜೈವ ವೈವಿಧ್ಯತೆ ಪರಿಸರ ವ್ಯವಸ್ಥೆಗಳ ಸ್ಥಿರತೆ, ಆಹಾರ, ಔಷಧೀಯ ಸಂಪನ್ಮೂಲಗಳು ಮತ್ತು ನೈಸರ್ಗಿಕ ಸೇವೆಗಳಿಗೆ ಮುಖ್ಯವಾಗಿದೆ. ವಿವಿಧ ಜೀವಿಗಳು ಪರಸ್ಪರ ಅವಲಂಬಿತವಾಗಿರುವುದರಿಂದ ಒಂದು ಜಾತಿಯ ನಷ್ಟವೂ ಪರಿಸರ ಸಮತೋಲನದ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರಬಹುದು. ವಾಸಸ್ಥಳ ರಕ್ಷಣೆ ಮತ್ತು ಅಕ್ರಮ ಬೇಟೆ ತಡೆ ಸಂರಕ್ಷಣೆಗೆ ಸಹಾಯಕ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಅರಣ್ಯ ನಾಶದ ಕಾರಣಗಳು ಮತ್ತು ಪರಿಣಾಮಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಕೃಷಿ ವಿಸ್ತರಣೆ, ನಗರೀಕರಣ, ಗಣಿಗಾರಿಕೆ, ಮರಕಡಿಯುವಿಕೆ ಮತ್ತು ಮೂಲಸೌಕರ್ಯ ಅಭಿವೃದ್ಧಿ ಅರಣ್ಯ ನಾಶಕ್ಕೆ ಕಾರಣವಾಗಬಹುದು. ಇದರಿಂದ ವಾಸಸ್ಥಳ ನಷ್ಟ, ಮಣ್ಣಿನ ಸವಕಳಿ, ಜೈವ ವೈವಿಧ್ಯತೆ ಕುಸಿತ ಮತ್ತು ಕಾರ್ಬನ್ ಹೊರಸೂಸುವಿಕೆ ಹೆಚ್ಚಳ ಸಂಭವಿಸಬಹುದು. ಪುನರ್ವನೀಕರಣ ಮತ್ತು ಸುಸ್ಥಿರ ಭೂಬಳಕೆ ಪರಿಹಾರಗಳಾಗಿವೆ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ವಾಯು ಮಾಲಿನ್ಯದ ಕಾರಣಗಳು ಮತ್ತು ನಿಯಂತ್ರಣ ಕ್ರಮಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ವಾಹನಗಳ ಹೊಗೆ, ಕೈಗಾರಿಕಾ ಹೊರಸೂಸುವಿಕೆ, ಕಲ್ಲಿದ್ದಲು ದಹನ ಮತ್ತು ತ್ಯಾಜ್ಯ ದಹನ ಪ್ರಮುಖ ಮೂಲಗಳು. ಸ್ವಚ್ಛ ಇಂಧನ, ಸಾರ್ವಜನಿಕ ಸಾರಿಗೆ, ಹೊರಸೂಸುವಿಕೆ ನಿಯಂತ್ರಣ, ಶಕ್ತಿ ದಕ್ಷತೆ ಮತ್ತು ಮರ ನೆಡುವಂತಹ ಕ್ರಮಗಳು ವಾಯು ಮಾಲಿನ್ಯ ಕಡಿಮೆ ಮಾಡಲು ಸಹಾಯ ಮಾಡುತ್ತವೆ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ನೀರಿನ ಮಾಲಿನ್ಯದ ಕಾರಣಗಳು ಮತ್ತು ಪರಿಣಾಮಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಕೈಗಾರಿಕಾ ತ್ಯಾಜ್ಯ, ಗೃಹ ತ್ಯಾಜ್ಯ ನೀರು, ಕೃಷಿ ರಾಸಾಯನಿಕಗಳ ಹರಿವು ಮತ್ತು ಪ್ಲಾಸ್ಟಿಕ್ ನೀರನ್ನು ಮಾಲಿನ್ಯಗೊಳಿಸಬಹುದು. ಇದರಿಂದ ಜಲಜೀವಿಗಳಿಗೆ ಹಾನಿ, ಕುಡಿಯುವ ನೀರಿನ ಗುಣಮಟ್ಟ ಕುಸಿತ ಮತ್ತು ರೋಗಗಳ ಅಪಾಯ ಹೆಚ್ಚಬಹುದು. ತ್ಯಾಜ್ಯ ನೀರಿನ ಶುದ್ಧೀಕರಣ ಮತ್ತು ಜಲಮೂಲ ರಕ್ಷಣೆ ಮುಖ್ಯ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಮಣ್ಣಿನ ಸವಕಳಿಯ ಕಾರಣಗಳು ಮತ್ತು ನಿಯಂತ್ರಣ ಕ್ರಮಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಅರಣ್ಯ ನಾಶ, ಅತಿಯಾದ ಮೇಯಿಸುವಿಕೆ, ತೀವ್ರ ಮಳೆ ಮತ್ತು ತಪ್ಪಾದ ಕೃಷಿ ಪದ್ಧತಿಗಳು ಮಣ್ಣಿನ ಸವಕಳಿಗೆ ಕಾರಣವಾಗಬಹುದು. ಮರ ನೆಡುವುದು, ಮಣ್ಣಿನ ಹೊದಿಕೆ, ಸಮತಟ್ಟಾದ ಕೃಷಿ ಪದ್ಧತಿ ಮತ್ತು ಸೂಕ್ತ ನೀರಿನ ನಿರ್ವಹಣೆ ಮೇಲ್ಮಣ್ಣನ್ನು ಕಾಪಾಡಲು ಸಹಾಯಕ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಹಸಿರುಮನೆ ಪರಿಣಾಮ ಮತ್ತು ಜಾಗತಿಕ ತಾಪಮಾನ ಏರಿಕೆಯನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಹಸಿರುಮನೆ ಅನಿಲಗಳು ಭೂಮಿಯ ಉಷ್ಣತೆಯ ಒಂದು ಭಾಗವನ್ನು ಹಿಡಿದಿಡುತ್ತವೆ. ಮಾನವ ಚಟುವಟಿಕೆಗಳಿಂದ ಕೆಲವು ಹಸಿರುಮನೆ ಅನಿಲಗಳ ಪ್ರಮಾಣ ಹೆಚ್ಚಿದಾಗ ಹೆಚ್ಚುವರಿ ಉಷ್ಣತೆ ಉಳಿಯಬಹುದು. ದೀರ್ಘಕಾಲದ ತಾಪಮಾನ ಏರಿಕೆಯು ಹವಾಮಾನ ಮಾದರಿ, ಸಮುದ್ರಮಟ್ಟ ಮತ್ತು ಪರಿಸರ ವ್ಯವಸ್ಥೆಗಳ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರುತ್ತದೆ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಹವಾಮಾನ ಬದಲಾವಣೆಯ ಪರಿಣಾಮಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ತಾಪಮಾನ ಏರಿಕೆ, ಮಳೆಯ ಮಾದರಿ ಬದಲಾವಣೆ, ತೀವ್ರ ಹವಾಮಾನ ಘಟನೆಗಳು, ಹಿಮನದಿಗಳ ಕರಗುವಿಕೆ ಮತ್ತು ಸಮುದ್ರಮಟ್ಟ ಏರಿಕೆ ಪ್ರಮುಖ ಪರಿಣಾಮಗಳಾಗಿವೆ. ಕೃಷಿ, ನೀರು, ಆರೋಗ್ಯ, ಜೀವ ವೈವಿಧ್ಯತೆ ಮತ್ತು ಕರಾವಳಿ ಪ್ರದೇಶಗಳ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರುವ ಸಾಧ್ಯತೆ ಇದೆ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ಹವಾಮಾನ ಬದಲಾವಣೆ ತಗ್ಗಿಸುವ ಮತ್ತು ಹೊಂದಿಕೊಳ್ಳುವ ಕ್ರಮಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ತಗ್ಗಿಸುವ ಕ್ರಮಗಳಲ್ಲಿ ಹಸಿರುಮನೆ ಅನಿಲ ಹೊರಸೂಸುವಿಕೆ ಕಡಿಮೆ ಮಾಡುವುದು, ನವೀಕರಿಸಬಹುದಾದ ಶಕ್ತಿ ಮತ್ತು ಅರಣ್ಯ ಸಂರಕ್ಷಣೆ ಸೇರಿವೆ. ಹೊಂದಾಣಿಕೆ ಕ್ರಮಗಳಲ್ಲಿ ಜಲ ಸಂರಕ್ಷಣೆ, ಮುನ್ನೆಚ್ಚರಿಕಾ ವ್ಯವಸ್ಥೆ, ಹವಾಮಾನ ಹೊಂದಾಣಿಕೆಯ ಕೃಷಿ ಮತ್ತು ವಿಪತ್ತು ಸಿದ್ಧತೆ ಸೇರಿವೆ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಸುಲಭ', '5', 'ನವೀಕರಿಸಬಹುದಾದ ಮತ್ತು ನವೀಕರಿಸಲಾಗದ ಸಂಪನ್ಮೂಲಗಳನ್ನು ಹೋಲಿಸಿ.', NULL, NULL, NULL, NULL, 'ಸೌರಶಕ್ತಿ, ಗಾಳಿಶಕ್ತಿ ಮತ್ತು ಜಲಶಕ್ತಿ ಮುಂತಾದ ಸಂಪನ್ಮೂಲಗಳು ಸೂಕ್ತ ನಿರ್ವಹಣೆಯೊಂದಿಗೆ ಮರುಪೂರಣಗೊಳ್ಳುತ್ತವೆ. ಕಲ್ಲಿದ್ದಲು ಮತ್ತು ಪೆಟ್ರೋಲಿಯಂ ಮುಂತಾದ ಸಂಪನ್ಮೂಲಗಳು ಸೀಮಿತವಾಗಿದ್ದು ರೂಪುಗೊಳ್ಳಲು ಬಹಳ ದೀರ್ಘಕಾಲ ಬೇಕಾಗುತ್ತದೆ. ಆದ್ದರಿಂದ ನವೀಕರಿಸಬಹುದಾದ ಸಂಪನ್ಮೂಲಗಳ ಬಳಕೆ ಹೆಚ್ಚಿಸುವುದು ದೀರ್ಘಕಾಲೀನ ಸಂರಕ್ಷಣೆಗೆ ಸಹಾಯಕ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ತ್ಯಾಜ್ಯ ನಿರ್ವಹಣೆಯ ಹಂತಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಮೊದಲು ತ್ಯಾಜ್ಯ ಉತ್ಪಾದನೆಯನ್ನು ಕಡಿಮೆ ಮಾಡಬೇಕು. ನಂತರ ತ್ಯಾಜ್ಯವನ್ನು ಮೂಲದಲ್ಲೇ ವಿಂಗಡಿಸಿ ಮರುಬಳಕೆ ಮತ್ತು ಮರುಸಂಸ್ಕರಣೆಗೆ ಯೋಗ್ಯವಾದ ವಸ್ತುಗಳನ್ನು ಬೇರ್ಪಡಿಸಬೇಕು. ಉಳಿದ ತ್ಯಾಜ್ಯವನ್ನು ಪರಿಸರಕ್ಕೆ ಹಾನಿಯಾಗದ ರೀತಿಯಲ್ಲಿ ವಿಲೇವಾರಿ ಮಾಡಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ಪ್ಲಾಸ್ಟಿಕ್ ಮಾಲಿನ್ಯದ ಪರಿಣಾಮಗಳು ಮತ್ತು ಪರಿಹಾರಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಪ್ಲಾಸ್ಟಿಕ್ ದೀರ್ಘಕಾಲ ಪರಿಸರದಲ್ಲಿ ಉಳಿಯಬಹುದು ಮತ್ತು ಜಲಜೀವಿಗಳು ಹಾಗೂ ಭೂಜೀವಿಗಳಿಗೆ ಹಾನಿ ಮಾಡಬಹುದು. ಏಕಬಳಕೆಯ ಪ್ಲಾಸ್ಟಿಕ್ ಬಳಕೆ ಕಡಿಮೆ ಮಾಡುವುದು, ಮರುಬಳಕೆ, ಮರುಸಂಸ್ಕರಣೆ ಮತ್ತು ಸೂಕ್ತ ವಿಲೇವಾರಿ ಪ್ರಮುಖ ಪರಿಹಾರಗಳಾಗಿವೆ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ನೀರಿನ ಸಂರಕ್ಷಣೆಯ ವಿಧಾನಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಮಳೆನೀರು ಸಂಗ್ರಹಣೆ, ಸೋರಿಕೆ ತಡೆ, ನೀರಿನ ಮಿತವ್ಯಯ, ಕೆರೆ ಮತ್ತು ಜಲಮೂಲಗಳ ಸಂರಕ್ಷಣೆ, ಕೃಷಿಯಲ್ಲಿ ಸೂಕ್ತ ನೀರಾವರಿ ಮತ್ತು ಮರುಬಳಕೆ ನೀರಿನ ಬಳಕೆ ಪ್ರಮುಖ ಕ್ರಮಗಳಾಗಿವೆ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ಮಣ್ಣಿನ ಸಂರಕ್ಷಣೆಯ ವಿಧಾನಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಮರ ನೆಡುವುದು, ಮಣ್ಣಿನ ಹೊದಿಕೆ, ಬೆಳೆ ಪರಿವರ್ತನೆ, ಜೈವಿಕ ಗೊಬ್ಬರ, ಅತಿಯಾದ ಮೇಯಿಸುವಿಕೆ ನಿಯಂತ್ರಣ ಮತ್ತು ಸೂಕ್ತ ನೀರಿನ ನಿರ್ವಹಣೆ ಮಣ್ಣಿನ ಸವಕಳಿ ಕಡಿಮೆ ಮಾಡಿ ಫಲವತ್ತತೆ ಕಾಪಾಡಲು ಸಹಾಯ ಮಾಡುತ್ತವೆ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ಸುಸ್ಥಿರ ಅಭಿವೃದ್ಧಿಯ ಅಂಶಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಸುಸ್ಥಿರ ಅಭಿವೃದ್ಧಿಯಲ್ಲಿ ಆರ್ಥಿಕ ಪ್ರಗತಿ, ಸಾಮಾಜಿಕ ಕಲ್ಯಾಣ ಮತ್ತು ಪರಿಸರ ಸಂರಕ್ಷಣೆಯನ್ನು ಸಮತೋಲನಗೊಳಿಸುವುದು ಮುಖ್ಯ. ಸಂಪನ್ಮೂಲಗಳ ಮಿತವ್ಯಯದ ಬಳಕೆ ಮತ್ತು ಭವಿಷ್ಯದ ಪೀಳಿಗೆಯ ಅಗತ್ಯಗಳನ್ನೂ ಪರಿಗಣಿಸಬೇಕು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ವನ್ಯಜೀವಿ ಸಂರಕ್ಷಣೆಯ ಅಗತ್ಯವನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ವನ್ಯಜೀವಿಗಳು ಪರಿಸರ ಸಮತೋಲನದಲ್ಲಿ ಪ್ರಮುಖ ಪಾತ್ರವಹಿಸುತ್ತವೆ. ವಾಸಸ್ಥಳ ನಾಶ, ಅಕ್ರಮ ಬೇಟೆ, ಮಾಲಿನ್ಯ ಮತ್ತು ಹವಾಮಾನ ಬದಲಾವಣೆ ಅವುಗಳಿಗೆ ಅಪಾಯ. ಸಂರಕ್ಷಿತ ಪ್ರದೇಶಗಳು, ವಾಸಸ್ಥಳ ರಕ್ಷಣೆ ಮತ್ತು ಕಾನೂನು ಜಾರಿ ಮೂಲಕ ಸಂರಕ್ಷಣೆ ಮಾಡಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ಓಜೋನ್ ಪದರದ ಮಹತ್ವವನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಓಜೋನ್ ಪದರ ಸೂರ್ಯನ ಹಾನಿಕಾರಕ ಅತಿನೇರಳೆ ಕಿರಣಗಳ ಬಹುಭಾಗವನ್ನು ಹೀರಿಕೊಳ್ಳುತ್ತದೆ. ಇದರ ರಕ್ಷಣೆ ಮಾನವ ಆರೋಗ್ಯ, ಸಸ್ಯಗಳು ಮತ್ತು ಪರಿಸರ ವ್ಯವಸ್ಥೆಗಳಿಗೆ ಮುಖ್ಯ. ಹಾನಿಕಾರಕ ರಾಸಾಯನಿಕಗಳ ಬಳಕೆಯನ್ನು ನಿಯಂತ್ರಿಸುವುದು ಸಹಾಯಕ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ಅಮ್ಲ ಮಳೆಯ ಕಾರಣಗಳು ಮತ್ತು ಪರಿಣಾಮಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಕೆಲವು ಕೈಗಾರಿಕಾ ಮತ್ತು ಇಂಧನ ದಹನದಿಂದ ಹೊರಬರುವ ಅನಿಲಗಳು ವಾತಾವರಣದಲ್ಲಿ ಪರಿವರ್ತನೆಗೊಂಡು ಮಳೆಯ ಆಮ್ಲೀಯತೆಯನ್ನು ಹೆಚ್ಚಿಸಬಹುದು. ಇದರಿಂದ ಜಲಮೂಲ, ಮಣ್ಣು, ಸಸ್ಯಗಳು ಮತ್ತು ಕಟ್ಟಡಗಳ ಮೇಲೆ ಪರಿಣಾಮ ಉಂಟಾಗಬಹುದು. ಹೊರಸೂಸುವಿಕೆ ನಿಯಂತ್ರಣ ಪರಿಹಾರವಾಗಿದೆ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ಧ್ವನಿ ಮಾಲಿನ್ಯದ ಕಾರಣಗಳು ಮತ್ತು ನಿಯಂತ್ರಣ ಕ್ರಮಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ವಾಹನಗಳು, ಕೈಗಾರಿಕೆಗಳು, ನಿರ್ಮಾಣ ಕಾರ್ಯಗಳು ಮತ್ತು ಅತಿಯಾದ ಧ್ವನಿವರ್ಧಕ ಬಳಕೆ ಧ್ವನಿ ಮಾಲಿನ್ಯಕ್ಕೆ ಕಾರಣವಾಗಬಹುದು. ಶಬ್ದದ ಮೂಲ ನಿಯಂತ್ರಣ, ಸಮಯ ಮಿತಿ, ಧ್ವನಿ ತಡೆಗೋಡೆ ಮತ್ತು ನಿಯಮಗಳ ಪಾಲನೆ ಸಹಾಯಕ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಮಧ್ಯಮ', '5', 'ನಗರೀಕರಣದ ಪರಿಸರ ಪರಿಣಾಮಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ನಗರ ವಿಸ್ತರಣೆಯಿಂದ ಭೂಬಳಕೆ ಬದಲಾವಣೆ, ವಾಹನ ಮಾಲಿನ್ಯ, ತ್ಯಾಜ್ಯ ಹೆಚ್ಚಳ, ನೀರಿನ ಬೇಡಿಕೆ ಮತ್ತು ಹಸಿರು ಪ್ರದೇಶಗಳ ಕಡಿತ ಸಂಭವಿಸಬಹುದು. ಸಾರ್ವಜನಿಕ ಸಾರಿಗೆ, ಹಸಿರು ಪ್ರದೇಶ, ತ್ಯಾಜ್ಯ ನಿರ್ವಹಣೆ ಮತ್ತು ಜಲ ಸಂರಕ್ಷಣೆಯ ಮೂಲಕ ಪರಿಣಾಮ ಕಡಿಮೆ ಮಾಡಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಪರಿಸರ ಶಿಕ್ಷಣದ ಮಹತ್ವವನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಪರಿಸರ ಶಿಕ್ಷಣವು ಪರಿಸರ ಸಮಸ್ಯೆಗಳು, ಕಾರಣಗಳು ಮತ್ತು ಪರಿಹಾರಗಳ ಬಗ್ಗೆ ಜ್ಞಾನ ನೀಡುತ್ತದೆ. ವ್ಯಕ್ತಿ ಮತ್ತು ಸಮುದಾಯಗಳಲ್ಲಿ ಜವಾಬ್ದಾರಿಯುತ ವರ್ತನೆ ಬೆಳೆಸಿ ನೀರು, ಶಕ್ತಿ ಮತ್ತು ಜೀವ ವೈವಿಧ್ಯತೆ ಸಂರಕ್ಷಣೆಗೆ ಪ್ರೇರೇಪಿಸುತ್ತದೆ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಮಳೆನೀರು ಸಂಗ್ರಹಣೆಯ ಪ್ರಯೋಜನಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಮಳೆನೀರು ಸಂಗ್ರಹಣೆಯಿಂದ ಸ್ಥಳೀಯ ನೀರಿನ ಲಭ್ಯತೆ ಹೆಚ್ಚಿಸಬಹುದು ಮತ್ತು ಭೂಗರ್ಭಜಲ ಮರುಪೂರಣಕ್ಕೆ ಸಹಾಯ ಮಾಡಬಹುದು. ನೀರಿನ ಕೊರತೆಯ ಅವಧಿಯಲ್ಲಿ ಸಂಗ್ರಹಿಸಿದ ನೀರನ್ನು ಸೂಕ್ತ ಬಳಕೆಗೆ ಬಳಸಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಕಾರ್ಬನ್ ಪಾದಚಿಹ್ನೆ ಕಡಿಮೆ ಮಾಡುವ ವಿಧಾನಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಸಾರ್ವಜನಿಕ ಸಾರಿಗೆ ಬಳಕೆ, ಶಕ್ತಿ ಉಳಿತಾಯ, ನವೀಕರಿಸಬಹುದಾದ ಶಕ್ತಿ, ಕಡಿಮೆ ಇಂಧನ ಬಳಕೆ, ಮರ ನೆಡುವುದು ಮತ್ತು ತ್ಯಾಜ್ಯ ಕಡಿತದ ಮೂಲಕ ಹಸಿರುಮನೆ ಅನಿಲ ಹೊರಸೂಸುವಿಕೆಯನ್ನು ಕಡಿಮೆ ಮಾಡಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಜೈವ ವೈವಿಧ್ಯತೆ ಸಂರಕ್ಷಣೆಯ ವಿಧಾನಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ವಾಸಸ್ಥಳ ಸಂರಕ್ಷಣೆ, ಸಂರಕ್ಷಿತ ಪ್ರದೇಶಗಳು, ಅಕ್ರಮ ಬೇಟೆ ತಡೆ, ಅರಣ್ಯ ಪುನರುತ್ಥಾನ ಮತ್ತು ಅಪಾಯದಲ್ಲಿರುವ ಜೀವಿಗಳ ರಕ್ಷಣೆ ಪ್ರಮುಖ ಕ್ರಮಗಳು. ಸ್ಥಳೀಯ ಸಮುದಾಯದ ಪಾಲ್ಗೊಳ್ಳುವಿಕೆಯೂ ಪರಿಣಾಮಕಾರಿ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ನೈಸರ್ಗಿಕ ಸಂಪನ್ಮೂಲ ಸಂರಕ್ಷಣೆಯ ಅಗತ್ಯವನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ನೀರು, ಮಣ್ಣು, ಅರಣ್ಯ ಮತ್ತು ಖನಿಜಗಳು ಮಾನವ ಜೀವನ ಹಾಗೂ ಆರ್ಥಿಕ ಚಟುವಟಿಕೆಗಳಿಗೆ ಅಗತ್ಯ. ಅತಿಯಾದ ಬಳಕೆ ಸಂಪನ್ಮೂಲ ಕ್ಷಯಕ್ಕೆ ಕಾರಣವಾಗಬಹುದು. ಮಿತವ್ಯಯ, ಪುನರುತ್ಪಾದನೆ ಮತ್ತು ಸುಸ್ಥಿರ ಬಳಕೆ ಭವಿಷ್ಯದ ಲಭ್ಯತೆಯನ್ನು ಕಾಪಾಡುತ್ತದೆ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ವಿಪತ್ತು ನಿರ್ವಹಣೆಯ ಹಂತಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಅಪಾಯ ಗುರುತಿಸುವಿಕೆ ಮತ್ತು ಮುನ್ನೆಚ್ಚರಿಕೆ, ಸಿದ್ಧತೆ, ತುರ್ತು ಪ್ರತಿಕ್ರಿಯೆ ಮತ್ತು ಪುನರ್ವಸತಿ ಪ್ರಮುಖ ಹಂತಗಳು. ಸಮುದಾಯ ಜಾಗೃತಿ, ಸುರಕ್ಷಿತ ಮೂಲಸೌಕರ್ಯ ಮತ್ತು ಮುನ್ನೆಚ್ಚರಿಕಾ ವ್ಯವಸ್ಥೆಗಳು ಹಾನಿ ಕಡಿಮೆ ಮಾಡಲು ಸಹಾಯಕ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಪರಿಸರ ಪರಿಣಾಮ ಮೌಲ್ಯಮಾಪನದ ಉದ್ದೇಶವನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಹೊಸ ಯೋಜನೆಯಿಂದ ನೀರು, ಗಾಳಿ, ಮಣ್ಣು, ಜೀವ ವೈವಿಧ್ಯತೆ ಮತ್ತು ಜನಜೀವನದ ಮೇಲೆ ಸಂಭವಿಸಬಹುದಾದ ಪರಿಣಾಮಗಳನ್ನು ಮುಂಚಿತವಾಗಿ ಗುರುತಿಸುವುದು ಇದರ ಉದ್ದೇಶ. ಹಾನಿ ಕಡಿಮೆ ಮಾಡುವ ಕ್ರಮಗಳನ್ನು ಯೋಜಿಸಲು ಇದು ಸಹಾಯ ಮಾಡುತ್ತದೆ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಪರಿಸರ ಸಂರಕ್ಷಣೆಯಲ್ಲಿ ವ್ಯಕ್ತಿ ಮತ್ತು ಸಮುದಾಯದ ಪಾತ್ರವನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ವ್ಯಕ್ತಿಗಳು ನೀರು ಮತ್ತು ಶಕ್ತಿ ಉಳಿಸುವುದು, ತ್ಯಾಜ್ಯ ವಿಂಗಡಿಸುವುದು, ಪ್ಲಾಸ್ಟಿಕ್ ಬಳಕೆ ಕಡಿಮೆ ಮಾಡುವುದು ಮತ್ತು ಮರ ನೆಡುವಂತಹ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳಬಹುದು. ಸಮುದಾಯಗಳು ಸ್ವಚ್ಛತಾ ಕಾರ್ಯಕ್ರಮ, ಜಲಮೂಲ ಸಂರಕ್ಷಣೆ ಮತ್ತು ಸ್ಥಳೀಯ ಪರಿಸರ ಯೋಜನೆಗಳಲ್ಲಿ ಒಟ್ಟಾಗಿ ಕೆಲಸ ಮಾಡಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಕಲ್ಪನೆಯ ಅರ್ಥ, ಕಾರಣಗಳು, ಪರಿಣಾಮಗಳು ಅಥವಾ ಪರಿಹಾರ ಕ್ರಮಗಳನ್ನು ಅಗತ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಪರಿಸರ ಮಾಲಿನ್ಯವನ್ನು ನಿಯಂತ್ರಿಸುವ ಸಮಗ್ರ ವಿಧಾನಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಪರಿಸರ ಮಾಲಿನ್ಯವನ್ನು ನಿಯಂತ್ರಿಸಲು ವಾಯು, ನೀರು, ಮಣ್ಣು ಮತ್ತು ಧ್ವನಿ ಮಾಲಿನ್ಯಗಳ ಮೂಲಗಳನ್ನು ಗುರುತಿಸಬೇಕು. ಕೈಗಾರಿಕಾ ಮತ್ತು ವಾಹನ ಹೊರಸೂಸುವಿಕೆಯನ್ನು ನಿಯಂತ್ರಿಸುವುದು, ತ್ಯಾಜ್ಯ ನೀರನ್ನು ಶುದ್ಧೀಕರಿಸುವುದು, ತ್ಯಾಜ್ಯವನ್ನು ಮೂಲದಲ್ಲೇ ವಿಂಗಡಿಸುವುದು, ಪ್ಲಾಸ್ಟಿಕ್ ಬಳಕೆ ಕಡಿಮೆ ಮಾಡುವುದು ಮತ್ತು ಶಬ್ದ ನಿಯಂತ್ರಣ ಕ್ರಮಗಳನ್ನು ಜಾರಿಗೊಳಿಸುವುದು ಅಗತ್ಯ. ಕಾನೂನು ಪಾಲನೆ, ಪರಿಸರ ಶಿಕ್ಷಣ ಮತ್ತು ಸಮುದಾಯದ ಪಾಲ್ಗೊಳ್ಳುವಿಕೆಯೂ ಮುಖ್ಯ.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಸರ ಸಂರಕ್ಷಣೆಗೆ ಸಂಬಂಧಿಸಿದ ಪ್ರಮುಖ ಕ್ರಮಗಳು ಮತ್ತು ಅವುಗಳ ಪ್ರಯೋಜನಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಪರಿಸರ ಸಮತೋಲನವನ್ನು ಕಾಪಾಡುವಲ್ಲಿ ಆಹಾರ ಸರಪಳಿ ಮತ್ತು ಆಹಾರ ಜಾಲದ ಪಾತ್ರವನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ಆಹಾರ ಸರಪಳಿಯಲ್ಲಿ ಉತ್ಪಾದಕರಿಂದ ಗ್ರಾಹಕರಿಗೆ ಶಕ್ತಿಯ ವರ್ಗಾವಣೆ ನಡೆಯುತ್ತದೆ. ಅನೇಕ ಆಹಾರ ಸರಪಳಿಗಳು ಪರಸ್ಪರ ಸಂಪರ್ಕಗೊಂಡಾಗ ಆಹಾರ ಜಾಲ ರೂಪುಗೊಳ್ಳುತ್ತದೆ. ಇದರಿಂದ ಪರಿಸರ ವ್ಯವಸ್ಥೆಯ ಜೀವಿಗಳು ಪರಸ್ಪರ ಅವಲಂಬಿತವಾಗಿರುವುದು ಸ್ಪಷ್ಟವಾಗುತ್ತದೆ. ಒಂದು ಜೀವಿಯ ಸಂಖ್ಯೆ ಅತಿಯಾಗಿ ಕಡಿಮೆಯಾದರೆ ಅಥವಾ ಹೆಚ್ಚಾದರೆ ಇತರ ಜೀವಿಗಳ ಮೇಲೂ ಪರಿಣಾಮ ಉಂಟಾಗಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಸರ ಸಂರಕ್ಷಣೆಗೆ ಸಂಬಂಧಿಸಿದ ಪ್ರಮುಖ ಕ್ರಮಗಳು ಮತ್ತು ಅವುಗಳ ಪ್ರಯೋಜನಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.'),
('KA-Environmental Science', 'ಕನ್ನಡ', 'ವಿಸ್ತೃತ ಉತ್ತರ', 'ಕಠಿಣ', '5', 'ಸುಸ್ಥಿರ ಜೀವನಶೈಲಿಯನ್ನು ಅಳವಡಿಸಿಕೊಳ್ಳುವ ಮಾರ್ಗಗಳನ್ನು ವಿವರಿಸಿ.', NULL, NULL, NULL, NULL, 'ನೀರು ಮತ್ತು ವಿದ್ಯುತ್ ಮಿತವ್ಯಯವಾಗಿ ಬಳಸುವುದು, ಸಾರ್ವಜನಿಕ ಸಾರಿಗೆ ಅಥವಾ ಹಂಚಿಕೆ ಸಾರಿಗೆ ಬಳಸುವುದು, ಏಕಬಳಕೆಯ ಪ್ಲಾಸ್ಟಿಕ್ ಕಡಿಮೆ ಮಾಡುವುದು, ವಸ್ತುಗಳನ್ನು ಮರುಬಳಕೆ ಮತ್ತು ಮರುಸಂಸ್ಕರಣೆ ಮಾಡುವುದು, ಸ್ಥಳೀಯ ಮತ್ತು ಅಗತ್ಯಕ್ಕೆ ತಕ್ಕ ಬಳಕೆಯನ್ನು ಉತ್ತೇಜಿಸುವುದು ಸುಸ್ಥಿರ ಜೀವನಶೈಲಿಯ ಭಾಗಗಳಾಗಿವೆ. ಮರ ನೆಡುವುದು ಮತ್ತು ತ್ಯಾಜ್ಯವನ್ನು ಸರಿಯಾಗಿ ವಿಂಗಡಿಸುವುದರಿಂದಲೂ ಪರಿಸರದ ಮೇಲಿನ ಒತ್ತಡ ಕಡಿಮೆ ಮಾಡಬಹುದು.', 'ಉತ್ತರದಲ್ಲಿ ಪರಿಸರ ಸಂರಕ್ಷಣೆಗೆ ಸಂಬಂಧಿಸಿದ ಪ್ರಮುಖ ಕ್ರಮಗಳು ಮತ್ತು ಅವುಗಳ ಪ್ರಯೋಜನಗಳನ್ನು ವಿವರಿಸಲಾಗಿದೆ.');